use ulw_loop_core::checkpoint::{checkpoint_ulw_loop, CheckpointUlwLoopArgs};
use ulw_loop_core::domain_types::*;
use ulw_loop_core::plan_io::write_plan;

fn c(id:&str,status:&str,essential:bool)->UlwLoopSuccessCriterion{UlwLoopSuccessCriterion{id:id.into(),scenario:"scenario".into(),user_model:"happy".into(),expected_evidence:"evidence".into(),status:status.into(),essential:Some(essential),captured_evidence:None,captured_at:None,notes:None,artifacts:None}}
fn g(id:&str,status:&str,cs:Vec<UlwLoopSuccessCriterion>)->UlwLoopItem{UlwLoopItem{id:id.into(),title:id.into(),objective:"Objective".into(),status:status.into(),success_criteria:cs,attempt:1,created_at:"2026-05-23T00:00:00Z".into(),updated_at:"2026-05-23T00:00:00Z".into(),started_at:None,completed_at:None,failed_at:None,review_blocked_at:None,evidence:None,failure_reason:None,steering_status:None,superseded_by:None,supersedes:None,blocked_reason:None,blocker_signature:None,blocker_occurrence_count:None,required_external_decision:None,non_retriable:None,steering_evidence:None,steering_rationale:None}}
fn p(gs:Vec<UlwLoopItem>)->UlwLoopPlan{UlwLoopPlan{version:1,revision:Some(1),codex_goal_mode:Some("aggregate".into()),brief:Some("brief".into()),ledger_reset_revision:None,evidence_layout_version:Some(2),goals_path:".omo/ulw-loop/goals.json".into(),ledger_path:".omo/ulw-loop/ledger.jsonl".into(),brief_path:".omo/ulw-loop/brief.md".into(),created_at:"2026-05-23T00:00:00Z".into(),updated_at:"2026-05-23T00:00:00Z".into(),active_goal_id:Some("G001".into()),goals:gs,codex_objective:Some("aggregate objective".into()),codex_objective_aliases:None,acknowledged_driver_objectives:None,aggregate_completion:None,validation_batches:None}}
fn run(plan:UlwLoopPlan, id:&str, snap:Option<&str>)->Result<ulw_loop_core::checkpoint::CheckpointUlwLoopResult,Box<dyn std::error::Error>>{let t=tempfile::tempdir()?;std::fs::create_dir_all(t.path().join(".omo/ulw-loop"))?;write_plan(t.path(),plan,None)?;let a=CheckpointUlwLoopArgs{goal_id:id.into(),status:"complete".into(),evidence:"implementation done and validation passed".into(),codex_goal_json:snap.map(str::to_string),quality_gate_json:None};Ok(checkpoint_ulw_loop(t.path(),&a,None,None)?) }
fn active()->String{serde_json::json!({"goal":{"objective":"aggregate objective","status":"active"}}).to_string()}

#[test] fn essential_pass_nonessential_pending_non_final_accepts(){let r=run(p(vec![g("G001","in_progress",vec![c("C001","pass",true),c("C002","pending",false)]),g("G002","pending",vec![])]),"G001",Some(&active())).unwrap();assert_eq!(r.goal.status,"complete");assert_eq!(r.ledger_entry.kind,"goal_completed");}
#[test] fn essential_pending_non_final_rejects(){let r=run(p(vec![g("G001","in_progress",vec![c("C001","pending",true),c("C002","pass",false)]),g("G002","pending",vec![])]),"G001",Some(&active()));assert!(r.is_err());}
#[test] fn essential_fail_or_blocked_rejects(){for s in ["fail","blocked"]{let r=run(p(vec![g("G001","in_progress",vec![c("C001","pass",true),c("C002",s,true),c("C003","pass",false)])]),"G001",None);assert!(r.is_err());}}
#[test] fn empty_criteria_rejects(){let r=run(p(vec![g("G001","in_progress",vec![]),g("G002","pending",vec![])]),"G001",Some(&active()));assert!(r.is_err());}
#[test] fn all_criteria_pass_accepts(){let r=run(p(vec![g("G001","in_progress",vec![c("C001","pass",true)]),g("G002","pending",vec![])]),"G001",Some(&active())).unwrap();assert_eq!(r.goal.status,"complete");assert_eq!(r.ledger_entry.kind,"goal_completed");}
#[test] fn matching_snapshot_succeeds(){assert_eq!(run(p(vec![g("G001","in_progress",vec![c("C001","pass",true)]),g("G002","pending",vec![])]),"G001",Some(&active())).unwrap().goal.status,"complete");}
#[test] fn mismatched_objective_warns(){let snap=serde_json::json!({"goal":{"objective":"wrong objective","status":"active"}}).to_string();let r=run(p(vec![g("G001","in_progress",vec![c("C001","pass",true)]),g("G002","pending",vec![])]),"G001",Some(&snap)).unwrap();assert!(r.warnings.join(" ").contains("driver_objective_differs"));}
#[test] fn closed_driver_advises_create_goal(){let snap=serde_json::json!({"goal":{"objective":"aggregate objective","status":"complete"}}).to_string();let r=run(p(vec![g("G001","in_progress",vec![c("C001","pass",true)]),g("G002","pending",vec![])]),"G001",Some(&snap)).unwrap();assert!(r.next_actions.join(" ").contains("create_goal"));}
